css:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --ink: #111009;
  --ink2: #4a4740;
  --ink3: #8a8780;
  --paper: #faf9f6;
  --paper2: #f2f0eb;
  --paper3: #e8e5de;
  --line: #dedad2;

  --amber: #671817;
  --amber-rgb: 103, 24, 23;
  --amber-light: #fdefef;
  --amber-light-rgb: 253, 239, 239;
  --amber-mid: #a96464;
  --amber-mid-rgb: 169, 100, 100;
  --amber-ink: #501613;
  --amber-ink-rgb: 80, 22, 19;
  --teal: #7a1a1a;
  --teal-rgb: 122, 26, 26;
  --teal-light: #fce8e8;
  --teal-light-rgb: 252, 232, 232;
  --teal-mid: #c28b8b;
  --teal-mid-rgb: 194, 139, 139;
  --rose: #5d1715;
  --rose-rgb: 93, 23, 21;
  --rose-light: #fcecec;
  --rose-light-rgb: 252, 236, 236;
  --rose-mid: #bb8181;
  --rose-mid-rgb: 187, 129, 129;}

html { scroll-behavior: smooth; }
/* PAGE MAX WIDTH */
nav, .hero, section, footer {
  max-width: 1600px;
  margin-left: auto;
  margin-right: auto;
}


body {
  background: var(--paper);
  color: var(--ink);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 15px;
  line-height: 1.65;
}

/* ── NAV ── */
nav {
  position: sticky; top: 0; z-index: 50;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
  padding: 0 48px;
  height: 52px;
  display: flex; align-items: center; justify-content: space-between;
}
.nav-back {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; color: var(--ink3);
  text-decoration: none;
  font-family: 'JetBrains Mono', monospace;
  transition: color 0.15s;
}
.nav-back:hover { color: var(--ink); }
.nav-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; color: var(--teal);
  background: var(--teal-light);
  padding: 3px 10px; border-radius: 3px;
  letter-spacing: 0.05em;
}

/* ── HERO ── */
.hero {
  background: linear-gradient(135deg, var(--paper) 60%, var(--teal-light) 100%);
  padding: 48px 48px 40px;
  border-bottom: 1px solid var(--line);
  position: relative; overflow: hidden;
}
.hero .float-svg {
  position: absolute; right: 48px; top: 50%;
  transform: translateY(-50%);
  width: 160px; height: 160px;
  color: var(--teal); opacity: 0.25;
  pointer-events: none;
}
.hero .float-svg svg { width: 100%; height: 100%; display: block; }
.hero-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--ink3);
  margin-bottom: 12px; position: relative; z-index: 1;
}
h1 {
  font-family: 'Fraunces', serif;
  font-size: 52px; font-weight: 300;
  line-height: 1.1; letter-spacing: -0.025em;
  color: var(--ink); margin-bottom: 12px;
  position: relative; z-index: 1;
}
h1 em { font-style: italic; color: var(--teal); }
.hero-desc {
  font-size: 16px; color: var(--ink2);
  line-height: 1.75; max-width: 520px;
  margin-bottom: 20px; position: relative; z-index: 1;
}
.meta-inline {
  display: flex; gap: 24px; flex-wrap: wrap;
  position: relative; z-index: 1;
}
.m-item { display: flex; flex-direction: column; gap: 1px; }
.m-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--ink3);
}
.m-value { font-size: 12px; color: var(--ink); font-weight: 500; }

/* ── SECTION ── */
section { padding: 64px 48px; border-bottom: 1px solid var(--line); }
.section-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--ink3);
  margin-bottom: 32px;
  display: flex; align-items: center; gap: 16px;
}
.section-label span {
  padding: 2px 8px;
  border: 1px solid var(--line);
  border-radius: 3px;
}
.section-label::after {
  content: ''; flex: 1; height: 1px; background: var(--line);
}
h2 {
  font-family: 'Fraunces', serif;
  font-size: 32px; font-weight: 300;
  letter-spacing: -0.015em;
  color: var(--ink); margin-bottom: 16px;
}
.prose { font-size: 15px; color: var(--ink2); line-height: 1.8; max-width: 680px; }
.prose + .prose { margin-top: 12px; }

/* ── SCENARIOS ── */
.scenarios { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-top: 32px; }
.scenario-card {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  opacity: 0; transform: translateY(12px);
  animation: fadeUp 0.4s ease forwards;
}
.scenario-card:nth-child(1) { animation-delay: 0.05s; }
.scenario-card:nth-child(2) { animation-delay: 0.12s; }
.scenario-card:nth-child(3) { animation-delay: 0.19s; }
.scenario-card:nth-child(4) { animation-delay: 0.26s; }
.scenario-card:nth-child(5) { animation-delay: 0.33s; }
.scenario-card:nth-child(6) { animation-delay: 0.40s; }
@keyframes fadeUp {
  to { opacity: 1; transform: translateY(0); }
}
.sc-icon { font-size: 22px; margin-bottom: 10px; }
.sc-title { font-size: 13px; font-weight: 600; color: var(--ink); margin-bottom: 6px; }
.sc-desc { font-size: 12px; color: var(--ink3); line-height: 1.55; }

/* ── TCR MATRIX ── */
.tcr-wrap { margin-top: 40px; }

/* Formula card */
.tcr-formula {
  display: inline-flex; align-items: center; gap: 16px;
  padding: 16px 24px;
  background: var(--amber-light);
  border: 1px solid var(--amber-mid);
  border-radius: 8px;
  margin-bottom: 32px;
}
.tcr-formula-text {
  font-family: 'JetBrains Mono', monospace;
  font-size: 14px; color: var(--amber-ink);
  letter-spacing: 0.04em;
}
.tcr-formula-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--amber); opacity: 0.72;
}

/* TCR threshold bar */
.tcr-threshold {
  margin-bottom: 32px;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}
.tcr-threshold-header {
  background: var(--paper2);
  padding: 10px 16px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--ink3);
  border-bottom: 1px solid var(--line);
}
.tcr-bar-wrap { padding: 20px; }
.tcr-bar {
  height: 12px; border-radius: 6px;
  background: linear-gradient(to right, var(--rose-light) 0%, var(--rose-light) 50%, var(--amber-light) 50%, var(--amber-light) 78%, var(--paper2) 78%, var(--paper2) 100%);
  border: 1px solid var(--line);
  margin-bottom: 8px;
  position: relative;
}
.tcr-bar-marker {
  position: absolute; top: -4px;
  width: 2px; height: 20px;
  background: var(--ink3);
}
.tcr-bar-labels {
  display: flex; justify-content: space-between;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.06em;
  margin-top: 6px;
}
.tcr-zone-labels {
  display: flex; gap: 0; margin-top: 12px;
}
.tcr-zone {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px; margin-right: 24px;
}
.tcr-zone-dot {
  width: 10px; height: 10px; border-radius: 2px; flex-shrink: 0;
}
.tz-red { background: var(--rose); }
.tz-amber { background: var(--amber); }
.tz-teal { background: var(--amber-ink); }

/* Completion matrix */
.matrix-wrap { margin-top: 0; }
.matrix-title {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--ink3); margin-bottom: 16px;
}
.tcr-matrix {
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
  max-width: 680px;
}
.matrix-header {
  display: grid; grid-template-columns: 120px repeat(4, 1fr) 80px;
  background: var(--paper2);
  padding: 8px 12px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--ink3);
  border-bottom: 1px solid var(--line);
  gap: 8px;
}
.matrix-row {
  display: grid; grid-template-columns: 120px repeat(4, 1fr) 80px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
  gap: 8px;
  align-items: center;
}
.matrix-row:last-child { border-bottom: none; }
.matrix-user { color: var(--ink3); font-family: 'JetBrains Mono', monospace; font-size: 11px; }
.cell-pass {
  background: var(--paper2);
  color: var(--amber-ink);
  border: 1px solid rgba(var(--amber-rgb),0.18);
  border-radius: 4px;
  padding: 3px 6px;
  font-size: 11px; font-weight: 600;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
}
.cell-fail {
  background: var(--rose-light);
  color: var(--rose);
  border-radius: 4px;
  padding: 3px 6px;
  font-size: 11px; font-weight: 600;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
}
.cell-rate-pass {
  background: var(--paper2);
  color: var(--amber-ink);
  border: 1px solid rgba(var(--amber-rgb),0.18);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 12px; font-weight: 600;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
}
.cell-rate-warn {
  background: var(--amber-light);
  color: var(--amber-ink);
  border: 1px solid rgba(var(--amber-rgb),0.24);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 12px; font-weight: 600;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
}
.cell-rate-fail {
  background: var(--rose-light);
  color: var(--rose);
  border: 1px solid rgba(var(--rose-rgb),0.18);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 12px; font-weight: 600;
  text-align: center;
  font-family: 'JetBrains Mono', monospace;
}
.matrix-task-rate {
  display: grid; grid-template-columns: 120px repeat(4, 1fr) 80px;
  padding: 8px 12px;
  background: var(--paper2);
  font-size: 11px;
  gap: 8px;
  align-items: center;
  border-top: 2px solid var(--line);
}
.mtr-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--ink3);
}

/* Variant cards */
.tcr-variants { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-top: 32px; }
.tv-card {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper2);
}
.tv-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--amber-ink); margin-bottom: 8px;
}
.tv-title { font-size: 14px; font-weight: 600; color: var(--ink); margin-bottom: 6px; }
.tv-desc { font-size: 12px; color: var(--ink3); line-height: 1.55; }

/* ── CASE STUDY ── */
.case-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 24px; margin-top: 40px;
}
.case-header {
  grid-column: 1 / -1;
  padding: 28px;
  background: var(--ink);
  border-radius: 10px;
  color: white;
  display: flex; align-items: center; justify-content: space-between;
}
.case-company {
  font-family: 'Fraunces', serif;
  font-size: 36px; font-weight: 300;
  letter-spacing: -0.02em;
}
.case-subtitle { font-size: 14px; color: rgba(255,255,255,0.5); margin-top: 6px; }
.case-year-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  background: rgba(255,255,255,0.12);
  padding: 6px 14px; border-radius: 4px;
  color: rgba(255,255,255,0.7);
}
.case-panel {
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
}
.panel-head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 16px;
}
.panel-icon {
  width: 32px; height: 32px; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; flex-shrink: 0;
}
.pi-teal { background: var(--teal-light); }
.pi-rose { background: var(--rose-light); }
.pi-amber { background: var(--amber-light); }
.panel-title { font-size: 13px; font-weight: 600; color: var(--ink); }
.panel-items { display: flex; flex-direction: column; gap: 8px; }
.pi-item {
  display: flex; gap: 10px; align-items: flex-start;
  font-size: 13px; color: var(--ink2);
}
.pi-bullet {
  width: 18px; height: 18px; border-radius: 50%;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 600; margin-top: 2px;
}
.bullet-teal { background: var(--teal-light); color: var(--teal); }
.bullet-rose { background: var(--rose-light); color: var(--rose); }
.bullet-amber { background: var(--amber-light); color: var(--amber); }

/* metric highlight */
.metric-row {
  grid-column: 1 / -1;
  padding: 16px 20px;
  background: var(--paper2);
  border-radius: 8px;
  border: 1px solid rgba(var(--amber-rgb),0.18);
  display: flex; align-items: flex-start; gap: 24px;
}
.metric-item { display: flex; flex-direction: column; gap: 4px; }
.metric-num {
  font-family: 'Fraunces', serif;
  font-size: 32px; font-weight: 300;
  color: var(--amber-ink); line-height: 1;
}
.metric-label { font-size: 12px; color: var(--amber); }
.metric-divider { width: 1px; background: rgba(var(--amber-rgb),0.18); align-self: stretch; }

/* GDS journey */
.gds-journey {
  grid-column: 1 / -1;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.gds-header {
  background: var(--paper2);
  padding: 16px 24px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--ink3);
  border-bottom: 1px solid var(--line);
}
.gds-row {
  display: flex; gap: 20px; align-items: flex-start;
  padding: 16px 24px;
  border-bottom: 1px solid var(--line);
}
.gds-row:last-child { border-bottom: none; }
.gds-phase {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
  width: 100px; flex-shrink: 0; padding-top: 2px;
}
.gds-phase-before { color: var(--rose); }
.gds-phase-after { color: var(--amber-ink); }
.gds-content { flex: 1; font-size: 13px; color: var(--ink2); line-height: 1.6; }
.gds-content strong { color: var(--ink); }
.gds-tcr {
  font-family: 'Fraunces', serif;
  font-size: 28px; font-weight: 300;
  flex-shrink: 0; width: 80px; text-align: right;
}
.gds-tcr-before { color: var(--rose); }
.gds-tcr-after { color: var(--amber-ink); }

/* ── STEPS ── */
.steps-flow { margin-top: 40px; display: flex; flex-direction: column; gap: 0; max-width: 760px; }
.step-card {
  display: flex; gap: 24px; align-items: flex-start;
}
.step-left {
  display: flex; flex-direction: column; align-items: center;
  flex-shrink: 0; width: 56px;
}
.step-num-circle {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--paper2);
  border: 2px solid var(--amber-mid);
  display: flex; align-items: center; justify-content: center;
  font-family: 'Fraunces', serif;
  font-size: 20px; font-weight: 300; color: var(--amber-ink);
  flex-shrink: 0; position: relative; z-index: 1;
}
.step-connector {
  width: 2px; flex: 1; min-height: 32px;
  background: var(--line);
  margin: 4px 0;
}
.step-body {
  flex: 1;
  padding: 0 0 40px;
}
.step-card:last-child .step-body { padding-bottom: 0; }
.step-card:last-child .step-connector { display: none; }

.step-header {
  display: flex; align-items: center; gap: 12px; margin-bottom: 4px;
}
.step-title { font-size: 16px; font-weight: 600; color: var(--ink); }
.step-duration {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em;
  color: var(--amber-ink);
  background: var(--amber-light);
  padding: 2px 8px; border-radius: 3px;
}
.step-desc {
  font-size: 14px; color: var(--ink2); line-height: 1.7;
  margin-bottom: 12px; margin-top: 8px;
}
.step-who {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px; color: var(--ink3); margin-bottom: 12px;
}
.step-who-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
}
.step-tip {
  padding: 12px 16px;
  background: var(--paper2);
  border-left: 3px solid var(--amber-mid);
  border-radius: 0 6px 6px 0;
  font-size: 13px; color: var(--ink2); line-height: 1.6;
}
.step-tip strong { color: var(--amber-ink); }

/* Task examples */
.task-examples { margin-bottom: 16px; }
.task-ex {
  display: flex; gap: 10px; align-items: flex-start;
  padding: 8px 12px;
  border-radius: 6px;
  margin-bottom: 6px;
  font-size: 13px; line-height: 1.5;
}
.task-ex-good { background: var(--paper2); color: var(--amber-ink); border: 1px solid rgba(var(--amber-rgb),0.16); }
.task-ex-bad { background: var(--rose-light); color: var(--rose); }
.task-ex-icon { flex-shrink: 0; font-weight: 700; }

/* ── FOOTER ── */
footer {
  padding: 48px 48px 40px;
  text-align: center;
  border-top: 1px solid var(--line);
  background: var(--paper);
}
.fc-progress-row {
  display: flex; align-items: center; justify-content: center;
  gap: 3px; margin-bottom: 24px; flex-wrap: wrap;
}
.fc-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--line); flex-shrink: 0; }
.fc-dot.visited { background: var(--teal); opacity: 0.4; }
.fc-dot.current { background: var(--teal); width: 20px; border-radius: 3px; }
.fc-ell {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3); margin: 0 4px;
}
.fc-progress-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3);
  margin-bottom: 20px; letter-spacing: 0.08em;
}
.fc-next-link {
  display: inline-flex; flex-direction: column; align-items: center;
  gap: 8px; padding: 24px 40px;
  border: 1px solid var(--teal); border-radius: 10px;
  background: var(--teal-light); transition: all 0.2s;
  text-decoration: none;
}
.fc-next-link:hover { background: var(--teal); }
.fc-next-link:hover .fc-nl-title,
.fc-next-link:hover .fc-nl-label,
.fc-next-link:hover .fc-nl-arrow { color: white; }
.fc-nl-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--teal); transition: color 0.2s;
}
.fc-nl-title {
  font-family: 'Fraunces', serif;
  font-size: 22px; font-weight: 300; color: var(--ink); transition: color 0.2s;
}
.fc-nl-arrow { font-size: 18px; color: var(--teal); transition: color 0.2s, transform 0.2s; }
.fc-next-link:hover .fc-nl-arrow { transform: translateX(4px); }
.fc-bottom {
  margin-top: 32px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3); opacity: 0.5;
}

@media (max-width: 900px) {
  .hero { padding: 32px 20px 28px; }
  h1 { font-size: 38px; }
  section { padding: 40px 20px; }
  nav { padding: 0 20px; }
  footer { padding: 32px 20px 28px; }
  .fc-next-link { padding: 20px 24px; }
  .fc-nl-title { font-size: 18px; }
  .scenarios { grid-template-columns: 1fr 1fr; }
  .case-grid { grid-template-columns: 1fr; }
  .tcr-variants { grid-template-columns: 1fr; }
  .metric-row { flex-direction: column; gap: 12px; }
  .metric-divider { display: none; }
  .matrix-header, .matrix-row, .matrix-task-rate { grid-template-columns: 80px repeat(4,1fr) 60px; font-size: 10px; }
}

    .skill-btn-meta {
      display: inline-flex; align-items: center; gap: 7px;
      font-family: 'JetBrains Mono', monospace;
      font-size: 11px; letter-spacing: 0.04em;
      color: var(--teal);
      background: var(--teal-light);
      border: 1px solid rgba(var(--teal-rgb),0.2);
      padding: 8px 16px; border-radius: 8px;
      cursor: pointer;
      transition: all 0.18s;
      text-decoration: none;
      margin-left: auto;
      align-self: center;
    }
    .skill-btn-meta:hover {
      background: var(--teal);
      color: white;
      border-color: var(--teal);
    }
    .skill-btn-meta svg {
      width: 14px; height: 14px;
      stroke: currentColor; fill: none;
      stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
    }

/* Nav fav button */
.nav-fav-group { display: flex; align-items: center; gap: 8px; }
.nav-fav-btn {
  font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.04em;
  color: var(--ink3); background: var(--paper2, #f2f0eb); border: 1px solid var(--line);
  padding: 3px 10px; border-radius: 3px; cursor: pointer; transition: all 0.15s;
  display: flex; align-items: center; gap: 4px;
}
.nav-fav-btn:hover { background: var(--paper3, #e8e5de); color: var(--ink2); }
.nav-fav-btn.is-fav { color: #b88010; background: #fdf8ec; border-color: #e8c870; }
/* SVG Assemble animation */
.hero .float-svg svg > * {
  opacity: 0; transform-origin: center;
  animation: assembleIn 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.hero .float-svg svg > *:nth-child(odd)  { transform: translate(-30px, -20px) rotate(-90deg); }
.hero .float-svg svg > *:nth-child(even) { transform: translate(30px, 20px) rotate(90deg); }
.hero .float-svg svg > *:nth-child(1)  { animation-delay: 0.05s; }
.hero .float-svg svg > *:nth-child(2)  { animation-delay: 0.11s; }
.hero .float-svg svg > *:nth-child(3)  { animation-delay: 0.17s; }
.hero .float-svg svg > *:nth-child(4)  { animation-delay: 0.23s; }
.hero .float-svg svg > *:nth-child(5)  { animation-delay: 0.29s; }
.hero .float-svg svg > *:nth-child(6)  { animation-delay: 0.35s; }
.hero .float-svg svg > *:nth-child(7)  { animation-delay: 0.41s; }
.hero .float-svg svg > *:nth-child(8)  { animation-delay: 0.47s; }
.hero .float-svg svg > *:nth-child(9)  { animation-delay: 0.53s; }
.hero .float-svg svg > *:nth-child(10) { animation-delay: 0.59s; }
.hero .float-svg svg > *:nth-child(11) { animation-delay: 0.65s; }
.hero .float-svg svg > *:nth-child(12) { animation-delay: 0.71s; }
@keyframes assembleIn { to { opacity: 1; transform: translate(0,0) rotate(0deg); } }

